import{_ as s,c as a,a as n,o as i}from"./app-DWIxxE3W.js";const l={};function o(u,e){return i(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="les-boucles-repeter-des-taches-automatiquement" tabindex="-1"><a class="header-anchor" href="#les-boucles-repeter-des-taches-automatiquement"><span>Les Boucles : Répéter des Tâches Automatiquement</span></a></h1><h2 id="pourquoi-avons-nous-besoin-de-boucles" tabindex="-1"><a class="header-anchor" href="#pourquoi-avons-nous-besoin-de-boucles"><span>Pourquoi Avons-Nous Besoin de Boucles ?</span></a></h2><p>Imaginez qu&#39;on vous demande d&#39;écrire la phrase &quot;Je ne bavarderai pas en classe&quot; sur un tableau noir 100 fois. Cela prendrait beaucoup de temps et vous ferait mal à la main !</p><p>En programmation, nous détestons faire la même chose encore et encore manuellement. Chaque fois qu&#39;un processus doit être répété, nous utilisons un outil appelé une <strong>boucle</strong> (loop).</p><p>Une boucle est simplement un ensemble d&#39;instructions que l&#39;ordinateur répète automatiquement jusqu&#39;à ce qu&#39;une condition d&#39;arrêt spécifique soit remplie. Les boucles rendent nos algorithmes efficaces et nous évitent de taper beaucoup de texte !</p><h2 id="la-boucle-for" tabindex="-1"><a class="header-anchor" href="#la-boucle-for"><span>La Boucle <code>FOR</code></span></a></h2><p>L&#39;une des façons les plus courantes de faire répéter une tâche à un ordinateur est d&#39;utiliser une <strong>boucle FOR</strong>. Une boucle FOR est parfaite lorsque vous savez exactement <em>combien de fois</em> vous voulez répéter quelque chose.</p><p>Voici à quoi ressemble la syntaxe en pseudo code :</p><div class="language-pseudo line-numbers-mode" data-highlighter="prismjs" data-ext="pseudo"><pre><code><span class="line">FOR compteur FROM 1 TO 4 DO</span>
<span class="line">  PRINT compteur</span>
<span class="line">END FOR</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Si vous exécutez cet algorithme, l&#39;ordinateur imprimera :</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">1</span>
<span class="line">2</span>
<span class="line">3</span>
<span class="line">4</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="decortiquer-la-boucle-for" tabindex="-1"><a class="header-anchor" href="#decortiquer-la-boucle-for"><span>Décortiquer la Boucle <code>FOR</code></span></a></h3><p>Regardons de plus près comment cela fonctionne :</p><ol><li><code>FOR compteur FROM 1</code> : Nous créons une variable temporaire nommée <code>compteur</code> et la démarrons à 1.</li><li><code>TO 4</code> : Nous disons à la boucle de continuer à se répéter jusqu&#39;à ce que le compteur atteigne 4.</li><li><code>DO</code> : Cela indique à l&#39;ordinateur d&#39;exécuter les instructions à l&#39;intérieur de la boucle.</li><li>Après chaque répétition, l&#39;ordinateur augmente automatiquement le compteur de 1.</li><li><code>END FOR</code> : Ceci marque la fin du bloc de la boucle.</li></ol><h3 id="un-exemple-concret" tabindex="-1"><a class="header-anchor" href="#un-exemple-concret"><span>Un Exemple Concret</span></a></h3><p>Utilisons une boucle <code>FOR</code> pour faire le compte à rebours des jours jusqu&#39;au week-end :</p><div class="language-pseudo line-numbers-mode" data-highlighter="prismjs" data-ext="pseudo"><pre><code><span class="line">FOR jour FROM 1 TO 5 DO</span>
<span class="line">  PRINT &quot;C&#39;est le jour &quot; + jour + &quot; de la semaine de travail.&quot;</span>
<span class="line">END FOR</span>
<span class="line"></span>
<span class="line">PRINT &quot;Hourra ! C&#39;est le week-end !&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Le résultat sera :</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code><span class="line">C&#39;est le jour 1 de la semaine de travail.</span>
<span class="line">C&#39;est le jour 2 de la semaine de travail.</span>
<span class="line">C&#39;est le jour 3 de la semaine de travail.</span>
<span class="line">C&#39;est le jour 4 de la semaine de travail.</span>
<span class="line">C&#39;est le jour 5 de la semaine de travail.</span>
<span class="line">Hourra ! C&#39;est le week-end !</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="la-boucle-while" tabindex="-1"><a class="header-anchor" href="#la-boucle-while"><span>La Boucle <code>WHILE</code></span></a></h2><p>Parfois, vous ne savez pas exactement combien de fois une boucle doit s&#39;exécuter. Vous voulez juste qu&#39;elle continue <strong>tant que</strong> (while) une certaine condition est vraie. Pour cela, nous utilisons une <strong>boucle WHILE</strong>.</p><div class="language-pseudo line-numbers-mode" data-highlighter="prismjs" data-ext="pseudo"><pre><code><span class="line">SET niveau_faim TO 5</span>
<span class="line"></span>
<span class="line">WHILE niveau_faim &gt; 0 DO</span>
<span class="line">  PRINT &quot;Manger une part de pizza...&quot;</span>
<span class="line">  SET niveau_faim TO niveau_faim - 1</span>
<span class="line">END WHILE</span>
<span class="line"></span>
<span class="line">PRINT &quot;Je suis rassasié !&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Cette boucle vérifiera la condition (<code>niveau_faim &gt; 0</code>). Si c&#39;est vrai, elle mange une part de pizza et diminue le niveau de faim. Elle répétera cela 5 fois jusqu&#39;à ce que le niveau de faim atteigne 0, moment auquel la boucle s&#39;arrête et imprime &quot;Je suis rassasié !&quot;.</p><p>Les boucles sont des outils incroyablement puissants que vous utiliserez tout le temps lors de la création d&#39;algorithmes !</p>`,24)])])}const t=s(l,[["render",o]]),c=JSON.parse('{"path":"/fr/loops.html","title":"Les Boucles : Répéter des Tâches Automatiquement","lang":"fr-FR","frontmatter":{},"headers":[{"level":2,"title":"Pourquoi Avons-Nous Besoin de Boucles ?","slug":"pourquoi-avons-nous-besoin-de-boucles","link":"#pourquoi-avons-nous-besoin-de-boucles","children":[]},{"level":2,"title":"La Boucle FOR","slug":"la-boucle-for","link":"#la-boucle-for","children":[{"level":3,"title":"Décortiquer la Boucle FOR","slug":"decortiquer-la-boucle-for","link":"#decortiquer-la-boucle-for","children":[]},{"level":3,"title":"Un Exemple Concret","slug":"un-exemple-concret","link":"#un-exemple-concret","children":[]}]},{"level":2,"title":"La Boucle WHILE","slug":"la-boucle-while","link":"#la-boucle-while","children":[]}],"git":{"updatedTime":1778106929000,"contributors":[{"name":"Aymane Benhima","username":"","email":"aymanebenhima.gmail.com","commits":2}],"changelog":[{"hash":"02c5b3cc51f9da680f9ea7a50ccdf218e1fb7b68","time":1778106929000,"email":"aymanebenhima.gmail.com","author":"Aymane Benhima","message":"feat: add multilingual documentation for variables, conditionals, and loops"},{"hash":"d0ac587de5ea00d050dbb9b4ba983301d2e58cae","time":1778105142000,"email":"aymanebenhima.gmail.com","author":"Aymane Benhima","message":"feat: initialize project with VuePress and multilingual documentation for JS fundamentals"}]},"filePathRelative":"fr/loops.md"}');export{t as comp,c as data};
